Definition xadd (X : Z -> list Z) (c a : Z) : Z -> list Z := fun c' => if c' =? c then a :: X c' else X c'.
Definition xdel (X : Z -> list Z) (c a : Z) : Z -> list Z := fun c' => if c' =? c then remove Z.eq_dec a (X c') else X c'.

