Lemma WF_lengths : forall st, WF st -> length (as_regions st) = 32%nat /\ length (as_cache st) = 32%nat.
Proof. intros st W. pose proof W as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & LR & LC & _). split; assumption. Qed.

